#include <vector>
#include <cstdio> // Use scanf for faster input
using namespace std;

int main() {
    int N, M, L, R = 0;
    scanf("%d %d", &N, &M); // Use scanf for faster input

    vector<int> s(N), t(N), e(N);
    vector<long long> d(N);

    // Change to a more efficient input method
    while (scanf("%d %d %d", &s[R], &t[R], &e[R]) == 3) {
        s[R]--, t[R]--; // Adjust indices
        if (!e[R]) break; 
        R++;
    }

    scanf("%d", &L); // Use scanf for faster input

    for (int i = 0; i < L; i++) {
        vector<int> c(M);
        for (int j = 0; j < M; j++) 
            scanf("%d", &c[j]); // Use scanf for faster input

        fill(d.begin(), d.end(), 0);

        for (int j = 0; j < R; j++) 
            d[s[j]] += c[t[j]] * e[j];

        for (int j = 0; j < N; j++) 
            cout << (j ? " " : "") << d[j];

        cout << endl;
    }
}

